# Homebrew cask for the RemoHop desktop app (RemoHop.app), generated by scripts/gen-manifests.sh
# from a release. It lives in the same tap as the formula (readori/homebrew-tap), at
# Casks/remohop-quick.rb:
#   brew install --cask readori/tap/remohop-quick
# The token is not "remohop" so that it cannot be confused with the formula (the CLI);
# it keeps its old name (from when RemoHop.app was quick support) so that installed
# copies keep upgrading.
cask "remohop-quick" do
  version "1.0.3"
  sha256 "b6ef85caaa9b71ef0c63b042e271e4f15436f8dc746323e9c6dfeb97e15fecea"

  url "https://github.com/readori/RemoHop/releases/download/v1.0.3/RemoHop-macos.dmg",
      verified: "github.com/readori/RemoHop/"
  name "RemoHop"
  desc "Remote desktop: connect to your computers and let others help on this Mac"
  homepage "https://remohop.com/"

  livecheck do
    url :url
    strategy :github_latest
  end

  depends_on macos: ">= :monterey"

  # Signed with a Developer ID, notarized and stapled; Homebrew installs it unchanged.
  app "RemoHop.app"

  # Only the app's own files: the rest of this directory is the remohop CLI's
  # identity and settings, shared with the formula.
  zap trash: [
    "~/Library/Application Support/remohop/desktop.json",
    "~/Library/Application Support/remohop/desktop.log",
    "~/Library/Application Support/remohop/desktop.url",
    "~/Library/Application Support/remohop/webview",
    "~/Library/LaunchAgents/com.remohop.app.plist",
    "~/Library/Application Support/remohop/quick.lang",
    "~/Library/Application Support/remohop/quick.log",
    "~/Library/Application Support/remohop/quick.url",
  ]
end
